-- Safety Center Compliance Checklist -- "Add to list", and a note that admits
-- it is optional.
--
-- Status: APPLIED to the live project (rewokyofschtvqgxrxwl) on 2026-10-01 via
-- psql (SUPABASE_DB_URL, ON_ERROR_STOP=1 --single-transaction).
--
-- WHAT CHANGED vs form-03
--
--   Every one of the 22 checklist questions gains
--   action_item_label: "Add to list". No field is added or removed; the schema
--   stays at 56 fields / 22 items / 5 stages.
--
-- WHY. "Create action item" is right on an inspection form and wrong on a
-- supply checklist: ticking "Disposable Gloves" is adding a line to an order,
-- not opening tracked work. The heavier phrasing, plus a note box whose
-- placeholder read "Action item title/description", is what made people retype
-- "order gloves" into a field that was never required -- an un-noted tick has
-- always fallen back to the question's own label.
--
-- NOT NEEDED FOR THE EMAIL. {parts.needed} is driven by flaggedFieldKeys, which
-- is ticked UNION negatives, and a "No" on a two-option eligible question is
-- already a negative. Answering No has always put the item in the order list
-- with its link. The tick is for the separate ACTION ITEM on /action-items.
--
-- Generated by scripts/gen-safety-center.ts, which is the source of truth.
-- Do not hand-edit the JSON; change the generator and re-run it.
--
-- TARGETS THE DRAFT via forms.draft_version_id. SAFE TO RE-RUN.
--
-- DOES NOTHING UNTIL SOMEBODY PRESSES PUBLISH, and the worker must be deployed
-- first: a worker predating action_item_label renders the default caption, so
-- publishing ahead of the deploy ships the old wording against the new schema.

update public.form_versions v
   set schema = '{"fields":[{"key":"site_number","type":"short_text","label":"Site number","helpText":"3-digit site number (leading zeros optional).","required":true,"maxLength":10,"id":"a9f66ff6"},{"key":"inspection_date","type":"date","label":"Inspection date","required":true,"defaultToToday":true,"id":"49131149"},{"key":"site_name","type":"lookup","label":"Site","required":false,"sourceTable":"pricing_simple","sourceColumn":"location_pretty","keyColumn":"pricing_simple.site","keyFieldId":"a9f66ff6","resolutionMode":"prefill_visible","nullBehavior":"allow_empty","id":"9ce5687b"},{"key":"rm_email","type":"lookup","label":"RM email","required":false,"sourceTable":"pricing_simple","sourceColumn":"rm_email","keyColumn":"pricing_simple.site","keyFieldId":"a9f66ff6","resolutionMode":"prefill_visible","nullBehavior":"allow_empty","id":"62289a42"},{"key":"site_email","type":"lookup","label":"Site email","required":false,"sourceTable":"pricing_simple","sourceColumn":"site_email","keyColumn":"pricing_simple.site","keyFieldId":"a9f66ff6","resolutionMode":"prefill_visible","nullBehavior":"allow_empty","id":"d0184168"},{"key":"manager","type":"short_text","label":"Manager","required":true,"maxLength":120,"id":"7cd78ae7"},{"key":"sec_ppe","type":"heading","label":"Personal Protective Equipment (PPE)","text":"Personal Protective Equipment (PPE)","level":"h3","required":false,"id":"c12b115b"},{"key":"ppe_safety_glasses","type":"radio","label":"Safety Glasses","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"action_item_label":"Add to list","id":"5d2bcdc8"},{"key":"ppe_safety_glasses_notes","type":"short_text","label":"Safety Glasses (notes)","required":false,"maxLength":300,"id":"861a836a"},{"key":"ppe_chemical_goggles","type":"radio","label":"Chemical Splash Goggles","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true