dd to list","id":"25c6f347"},{"key":"equip_wheel_chocks_notes","type":"short_text","label":"Wheel Chocks (notes)","required":false,"maxLength":300,"id":"523db4dc"},{"key":"equip_loto","type":"radio","label":"Lockout/Tagout (LOTO) Locks and Tags","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"action_item_label":"Add to list","id":"8bb7a6cd"},{"key":"equip_loto_notes","type":"short_text","label":"Lockout/Tagout (LOTO) Locks and Tags (notes)","required":false,"maxLength":300,"id":"0e4c3f58"},{"key":"equip_spill_kit","type":"radio","label":"Spill Kit Fully Stocked","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"action_item_label":"Add to list","id":"baa9b8d9"},{"key":"equip_spill_kit_notes","type":"short_text","label":"Spill Kit Fully Stocked (notes)","required":false,"maxLength":300,"id":"c030ee65"},{"key":"sec_prog","type":"heading","label":"Required Safety Programs","text":"Required Safety Programs","level":"h3","required":false,"id":"fffa48fa"},{"key":"prog_hazcom","type":"radio","label":"Hazard Communication (HazCom) Program","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"action_item_label":"Add to list","id":"af081582"},{"key":"prog_hazcom_notes","type":"short_text","label":"Hazard Communication (HazCom) Program (notes)","required":false,"maxLength":300,"id":"70cd2f04"},{"key":"prog_spill_response","type":"radio","label":"Spill Response Program","layout":"inline","options":[{"label":"Yes","value":"yes"},{"label":"No","value":"no"}],"required":true,"action_item_eligible":true,"action_item_label":"Add to list","id":"caa4c54e"},{"key":"prog_spill_response_notes","type":"short_text","label":"Spill Response Program (notes)","required":false,"maxLength":300,"id":"67c71399"},{"key":"prog_sds","type":"radio","label":"S