field","field_key":"rm_email"}],"subject_template":"Safety Center checklist for review - {field.site_name} (site {field.site_number})","body_template":"{field.manager} completed the Safety Center Compliance Checklist for {field.site_name} (site {field.site_number}) on {field.inspection_date}.\n\nThe completed checklist is attached, including any corrective action items raised. Those items are also on the site''s action items page.\n\nReview here:\n\n{submission.url}","attach_pdf":true,"transitions":[{"to":"rm_review","label":"Move to RM review"}]},{"id":"rm_review","label":"RM review","kind":"approval","approver_source":{"type":"payload_field","field_key":"rm_email"},"transitions":[{"to":"reviewed","label":"Mark reviewed","requires":{"typed_name":true}},{"to":"returned","label":"Send back","requires":{"note":true}}]},{"id":"reviewed","label":"Reviewed","kind":"outcome","tint":"success","transitions":[]},{"id":"returned","label":"Sent back","kind":"outcome","tint":"warning","transitions":[]}]}}'::jsonb
  from public.forms f
 where f.slug = 'safety-center'
   and v.id = f.draft_version_id;

select jsonb_array_length(v.schema->'fields') as fields,
       (select count(*) from jsonb_array_elements(v.schema->'fields') e
         where e->>'action_item_label' = 'Add to list') as labelled,
       (select count(*) from jsonb_array_elements(v.schema->'fields') e
         where (e->>'action_item_eligible')::boolean) as eligible
  from public.forms f
  join public.form_versions v on v.id = f.draft_version_id
 where f.slug = 'safety-center';
